const themes = [
  'Cursos online',
  'Programação',
  'Inteligência Artificial',
  'Cursos em Moçambique',
  'Melhores cursos para jovens',
  'Cursos para o mercado de emprego',
  'Marketing digital',
  'Tecnologia',
  'Empreendedorismo',
  'Profissões em alta',
  'Desenvolvimento web',
  'Educação profissional'
];

const randomTheme = themes[Math.floor(Math.random() * themes.length)];

const staticData = $getWorkflowStaticData('global');
staticData.runCount = staticData.runCount || 0;
staticData.runCount++;

const language = (staticData.runCount % 2 === 0) ? 'English' : 'Português';

return { theme: randomTheme, language: language };

let content = $json.message.content;

// Remover formatação markdown (se o ChatGPT enviar)
if (content.startsWith('```json')) {
  content = content.replace(/^```json\n?/, '').replace(/\n?```$/, '');
} else if (content.startsWith('```')) {
  content = content.replace(/^```\n?/, '').replace(/\n?```$/, '');
}

const seoData = JSON.parse(content);
return { ...seoData, theme: $('Set Theme and Language').item.json.theme, language: $('Set Theme and Language').item.json.language };

