const seo = $('Parse SEO JSON').item.json;
const content = $('Generate Article Content').item.json.message.content;
const pexels = $('Search Pexels Images').item.json;

// Pega a primeira imagem do Pexels para ser a capa do artigo (cover_url)
let cover_url = null;
if (pexels && pexels.photos && pexels.photos.length > 0) {
  cover_url = pexels.photos[0].src.large2x || pexels.photos[0].src.large;
}

return {
  title: seo.title || "Sem Titulo",
  content: content || "",
  seo_title: seo.title || "",
  seo_description: seo.metaDescription || "",
  slug: seo.slug || "artigo-" + Date.now(),
  category: seo.category || "Geral",
  tags: seo.tags || [],
  is_published: false,
  excerpt: seo.excerpt || "",
  primary_keyword: seo.keyword || "",
  secondary_keywords: seo.secondaryKeywords || [],
  llm_summary: seo.llm_summary || "",
  key_takeaways: seo.key_takeaways || [],
  cover_alt: seo.cover_alt || seo.keyword,
  reading_minutes: seo.reading_minutes || 5,
  cover_url: cover_url
};
